1530	  /* Selected floods with saturated colour and lifts — an outline alone reads
1531	     flat — and its rim is a cyan-to-magenta gradient that TRAVELS around the
1532	     card. Same `--orbit` angle the liquid-glass card uses, so the two effects
1533	     are one idea rather than two lookalikes.
1534	
1535	     The rim is a conic gradient painted into `border-box` with a solid
1536	     `padding-box` fill on top; the border itself is transparent, so the
1537	     gradient shows only in the border's width. That is what lets it curve the
1538	     corners — a `border-image` cannot. */
1539	  .card-on {
1540	    border-width: 1.5px;
1541	    border-color: transparent;
1542	    background:
1543	      linear-gradient(#04214f, #04214f) padding-box,
1544	      conic-gradient(from var(--orbit),
1545	        #14c5e4 0deg, #6be6ff 40deg, #2f7eef 100deg,
1546	        #8c3ae9 170deg, #d623e1 215deg, #ff8cf2 255deg,
1547	        #8c3ae9 300deg, #14c5e4 360deg) border-box;
1548	    /* The outer light is a SHADOW, not a blurred pseudo-element. A `::after`
1549	       glow would need `z-index: -1` to sit behind the card, and a negative
1550	       z-index only paints behind a parent that establishes a stacking context —
1551	       `.card` is `position: relative` with no z-index, so it does not, and the
1552	       glow would have been invisible. Two shadows in the rim's own colours do
1553	       the same job with no stacking games. */
1554	    box-shadow: inset 0 0 16px -6px rgba(0,190,255,0.20),
1555	                0 0 24px -8px rgba(20,197,228,0.45),
1556	                0 0 30px -10px rgba(214,35,225,0.35),
1557	                0 10px 26px rgba(0,3,10,0.74);
1558	    animation: lgc-orbit 6s linear infinite;
1559	  }
1560	  /* A travelling rim on a control the customer is mid-decision on is exactly
1561	     the kind of motion that becomes a distraction; reduced-motion parks it on
1562	     a static frame rather than removing the colour. */
