63	/** The tag itself — no pill, no fill, no border. A small glowing dot with an
64	 *  off-axis bleed, plain white text (or dim grey for the neutral "slate"
65	 *  tone, which never glows at all — the absence of light IS the signal that
66	 *  nothing here needs a look). See the "light, not shape" study. */
67	function StatusTag({ label, tone, pulse, className = "" }: {
68	  label: string; tone: string; pulse?: boolean; className?: string;
69	}) {
70	  /* The neutral tone used to render as bare text with no dot at all — the
71	     idea being that an absence of light is itself the signal. In practice it
72	     read as the column being empty/broken rather than "quiet on purpose":
73	     nothing marks where a status is even supposed to be. Every tone now gets
74	     the same dot + label shape; slate's dot just never lights up. Structure
75	     stays constant, only the light changes. */
76	  return (
77	    <span className={"nx-tag nx-tag-" + tone + (pulse ? " nx-tag-pulse" : "") + " " + className}>
