1	// Server-side resolver for the visitor's DISPLAY currency + the active FX rates.
2	//
3	// This is the glue between the pure layers (lib/geo-currency.ts, the FX helpers in
4	// lib/tax.ts) and Next's request context (`headers()` / `cookies()`). Import it
5	// from server components / layouts only — it reads the Setting store (db).
6	//
7	// DISPLAY vs CHARGE: everything here decides only how prices are SHOWN. The charge
8	// currency is USD and is untouched. See the boundary note in lib/tax.ts.
9	
10	import "server-only";
11	import { cookies, headers } from "next/headers";
12	import {
13	  CURRENCIES,
14	  CURRENCY_COOKIE,
15	  DEFAULT_CURRENCY,
16	  parseRatesOverride,
17	  rateFor,
18	} from "./currency";
19	import { getSetting } from "./settings";
20	import { countryFromHeaders, currencyForCountry } from "./geo-currency";
21	import { countryFromRequestIp } from "./geo-ip";
22	
23	export { CURRENCY_COOKIE };
24	
25	/** How the display currency was chosen — surfaced for debugging / the switcher UI. */
26	export type CurrencySource = "cookie" | "geo" | "default";
27	
28	export type ResolvedCurrency = {
29	  /** The chosen DISPLAY currency code (always a key of CURRENCIES). */
30	  currency: string;
31	  /** Where the choice came from. */
32	  source: CurrencySource;
33	  /** Full rates table (target units per USD), admin-override merged over defaults. */
34	  rates: Record<string, number>;
35	  /** The chosen currency's rate — `rates[currency]`, guaranteed > 0. */
36	  rate: number;
37	};
38	
39	/** Validate a code against the currencies we can actually render. */
40	function validCurrency(code: string | null | undefined): string | null {
41	  const c = (code ?? "").trim().toUpperCase();
42	  return c && CURRENCIES[c] ? c : null;
43	}
44	
45	/** The active FX rates: the admin `currency_rates` override merged over defaults. */
46	export async function getCurrencyRates(): Promise<Record<string, number>> {
47	  return parseRatesOverride(await getSetting("currency_rates"));
48	}
49	
50	/**
51	 * Resolve the visitor's display currency for the current request.
52	 *
53	 * Precedence:
54	 *   1. `nx_currency` cookie — an explicit manual choice from the switcher wins.
55	 *   2. CDN/proxy country header (Cloudflare `cf-ipcountry` etc.) → mapped currency.
56	 *   3. IP → country via the bundled geoip-lite dataset (works with no CDN in
57	 *      front; the header path in step 2 wins whenever a CDN is added later).
58	 *   4. The operator's configured default `currency` Setting (USD out of the box).
59	 *
60	 * Anything unrecognised at each step falls through to the next, and the final
61	 * fallback is always a currency we can render. Never throws.
62	 */
63	export async function resolveDisplayCurrency(): Promise<ResolvedCurrency> {
64	  const [jar, hdrs, rates, configuredDefault] = await Promise.all([
65	    cookies(),
66	    headers(),
67	    getCurrencyRates(),
68	    getSetting("currency"),
69	  ]);
70	
71	  const fallback = validCurrency(configuredDefault) ?? DEFAULT_CURRENCY;
72	
73	  let currency = fallback;
74	  let source: CurrencySource = "default";
75	
76	  const cookieChoice = validCurrency(jar.get(CURRENCY_COOKIE)?.value);
77	  if (cookieChoice) {
78	    currency = cookieChoice;
79	    source = "cookie";
80	  } else {
81	    // CDN/proxy header first; else resolve the country from the client IP with
82	    // the local geoip-lite dataset (no CDN required). NB: countryFromHeaders
83	    // returns "" (not null) when absent, so use || — not ?? — to fall through.
84	    const country = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs);
85	    if (country) {
86	      const geoCurrency = validCurrency(currencyForCountry(country));
87	      // Only treat geo as decisive when it actually places the visitor somewhere
88	      // with a non-default currency; otherwise keep the operator default.
89	      if (geoCurrency && geoCurrency !== fallback) {
90	        currency = geoCurrency;
91	        source = "geo";
92	      } else if (geoCurrency) {
93	        source = "geo";
94	      }
95	    }
96	  }
97	
98	  return { currency, source, rates, rate: rateFor(rates, currency) };
99	}
