  const label = refunded && status !== "REFUNDED" ? "Part refunded" : status.toLowerCase();
  if (status === "PAID" && !refunded) {
    return <span className="badge badge-mint flex-none text-[10.5px] capitalize">{label}</span>;
  }
  if (status === "OPEN") {
    return <span className="badge badge-amber flex-none text-[10.5px] capitalize">{label}</span>;
