/* Was `.badge`/`badge-mint`/`badge-amber`/`badge-cyan` — a saturated-fill
   sticker pill. SupportView's ticket status/priority tags moved off that
   exact convention to `.nx-tag` (the "light, not shape" study: no pill, no
   fill, no border — a small glowing dot with an off-axis bleed instead), and
   left this row as the one place still drawing the old loud sticker. Same
   tone keys (mint/amber/cyan), same neutral "slate" fallback, just the
   current shape so a "Paid" invoice reads as considered rather than a
   default-looking green pill. */
function StatusPill({ status, refunded }: { status: string; refunded: boolean }) {
  const label = refunded && status !== "REFUNDED" ? "Part refunded" : status.toLowerCase();
  const tone =
    status === "PAID" && !refunded ? "mint" :
    status === "OPEN" ? "amber" :
    status === "REFUNDED" || refunded ? "cyan" :
    "slate";
  return (
    <span className={"nx-tag nx-tag-" + tone + " flex-none capitalize"}>
      <span className="nx-tag-dot" aria-hidden />
      {label}
    </span>
  );
}

